#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"; BIN=${BIN:-$ROOT/build-cutest/lazyipdca_cutest}; MANIFEST=${MANIFEST:-$ROOT/benchmarks/manifests/cutest37.csv}; OUT=${OUT:-$ROOT/results/runs/cutest37_abcd_$(date +%Y%m%d_%H%M%S)}; mkdir -p "$OUT"
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 BLIS_NUM_THREADS=1 NUMEXPR_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1
COMMON_PRE=(--manifest "$MANIFEST" --regularization-mode lazy --init 2 --backend ldl --rho-trial-every 2 --max-atoms 500 --seed-coverage 0.25 --seed-stall-tol 0 --seed-patience 999 --bound-push 0 --bp-push-kappa 1e-4 --bp-margin-tol 1e-4 --escapes 3 --mehrotra)
COMMON_POST=(--sigma-max 1e14 --model-solved-tol 1e-12 --dca-stop --dca-stall-tol-rel 1e-10 --dca-stall-iters 5 --dca-monotone-tol-abs 1e-6 --bp-adaptive --max-iter 3000 --time-limit 36000 --eps 1e-6 --verbose 1 --no-atom-cluster)
NO_MOM=(--dca-momentum original --no-momentum-complete --dca-acceptance lyapunov); EVENTS=(--atom-events --atom-event-every 50 --atom-update-every 20 --atom-every-iters 10 --atoms-per-update 1)
C_RETURN=(--no-adaptive-seed-return --adaptive-marginal-return --adaptive-return-warmup 4 --adaptive-return-window 3 --adaptive-return-confirmations 2 --adaptive-return-alpha-lift 0.20 --adaptive-return-alpha-effective 0.20 --adaptive-return-lift-min 1e-5 --adaptive-return-lift-max 1e-3 --adaptive-return-effective-min 1e-5 --adaptive-return-effective-max 2.5e-3 --adaptive-return-cooldown-factor 2.0 --adaptive-return-cooldown-max-factor 8.0 --adaptive-return-strong-factor 4.0 --adaptive-return-seed-alpha-coverage 0.20 --adaptive-return-seed-alpha-lift 0.20 --adaptive-return-seed-coverage-min 1e-5 --adaptive-return-seed-coverage-max 2.5e-3 --adaptive-return-seed-lift-min 1e-5 --adaptive-return-seed-lift-max 1e-3 --no-adaptive-return-seed-absolute --adaptive-return-seed-plateau --adaptive-return-seed-plateau-horizon 8 --adaptive-return-seed-plateau-min-commits 12 --adaptive-return-seed-plateau-confirmations 2 --adaptive-return-seed-plateau-coverage 2.5e-3 --adaptive-return-seed-plateau-lift 1e-3)
A=("${COMMON_PRE[@]}" --legacy-atoms "${COMMON_POST[@]}" "${NO_MOM[@]}" "${EVENTS[@]}" --max-seed-atoms 0); B=("${COMMON_PRE[@]}" --legacy-atoms "${COMMON_POST[@]}" "${NO_MOM[@]}" "${EVENTS[@]}" --max-seed-atoms 20); C=("${COMMON_PRE[@]}" --adaptive-atoms "${COMMON_POST[@]}" "${NO_MOM[@]}" "${EVENTS[@]}" "${C_RETURN[@]}" --max-seed-atoms 0 --atom-oracle-min-directional-ratio 0.10); D=("${COMMON_PRE[@]}" --adaptive-atoms "${COMMON_POST[@]}" "${NO_MOM[@]}" "${EVENTS[@]}" "${C_RETURN[@]}" --max-seed-atoms 20 --atom-oracle-min-directional-ratio 0.10)
mapfile -t TAGS < <(python "$ROOT/benchmarks/cutest37/tags_from_manifest.py" "$MANIFEST")
for arm in A B C D; do declare -n ARGS="$arm"; for tag in "${TAGS[@]}"; do echo "===== $arm $tag ====="; "$BIN" "${ARGS[@]}" --problem "$tag" --outdir "$OUT/$arm/$tag" > "$OUT/${arm}_${tag}.log" 2>&1 || true; done; done
echo "$OUT"
